+            Workgroup Details — {details?.workgroup.name ?? workgroupName}
+          </h5>
+          <button type="button" className="btn-close" aria-label="Close workgroup details" onClick={handleClose} />
+        </div>
+        <div className="modal-body p-3">
+          {error ? (
